/**
 * MetaSync metadata ingest — pure logic (DESIGN-METADATA.md §6/§9/§12).
 *
 * The canonical form, claim shapes, and caps here MIRROR the Python
 * shared library (node/metasync_node/meta/claims.py, PR #10) exactly:
 * the batch digest a node signs in Python must be the digest this
 * function verifies. Cross-language agreement is pinned by
 * tests/fixtures/meta-batch-fixture.json, generated by the Python
 * implementation; tests/metasync-claims.test.ts fails if the two ever
 * diverge.
 *
 * One deliberate difference: the Python validator also recomputes the
 * SoulID from each name claim. That check needs the kinded_v2
 * normalizer, which exists exactly once (Python); porting it here
 * would create a third implementation. Ingest therefore validates
 * structure, enums, shapes, and caps — and the compiler worker
 * re-validates every claim (recompute included) before anything can
 * publish. A bogus name claim can be stored; it can never be used.
 */
import { createHmac, verify as cryptoVerify } from "node:crypto";
import {
  decodeBase64Url,
  ed25519PublicKeyObject,
  isTimestampWithinWindow,
  sha256Hex,
  verifyNodeSignature,
} from "../sin/logic.ts";

/* ---------------- canonical form (JCS subset) ---------------- */

/** Canonical bytes for a batch payload. Floats and unsafe integers
 *  are refused: JCS number serialization is where canonical-JSON
 *  implementations diverge, and claim values never need them. */
export function canonicalBytes(value: unknown): Buffer {
  return Buffer.from(canonicalString(value), "utf-8");
}

/** Strings a batch may never contain: Postgres jsonb refuses NUL,
 *  and an unpaired surrogate cannot be encoded to UTF-8. Python's
 *  canonical form refuses both at construction; refuse identically
 *  here so a signed batch can never wedge the ingest mid-write. */
function checkBatchString(s: string): void {
  if (s.includes("\u0000")) {
    throw new ClaimError("NUL character forbidden in batch");
  }
  for (let i = 0; i < s.length; i++) {
    const code = s.charCodeAt(i);
    if (code >= 0xd800 && code <= 0xdbff) {
      const next = s.charCodeAt(i + 1);
      if (!(next >= 0xdc00 && next <= 0xdfff)) {
        throw new ClaimError("unpaired surrogate in batch");
      }
      i++;
    } else if (code >= 0xdc00 && code <= 0xdfff) {
      throw new ClaimError("unpaired surrogate in batch");
    }
  }
}

/** Code-point comparison, matching Python's sort_keys (JS's default
 *  string sort is by UTF-16 unit and disagrees when astral characters
 *  meet U+E000–U+FFFF characters in keys). */
function compareCodePoints(a: string, b: string): number {
  const ai = [...a];
  const bi = [...b];
  for (let i = 0; i < Math.min(ai.length, bi.length); i++) {
    const d = ai[i].codePointAt(0)! - bi[i].codePointAt(0)!;
    if (d !== 0) return d;
  }
  return ai.length - bi.length;
}

function canonicalString(value: unknown): string {
  if (value === null) return "null";
  if (typeof value === "boolean") return value ? "true" : "false";
  if (typeof value === "number") {
    if (!Number.isInteger(value) || !Number.isSafeInteger(value)) {
      throw new ClaimError("non-integer or unsafe number in batch");
    }
    return String(value);
  }
  if (typeof value === "string") {
    checkBatchString(value);
    return JSON.stringify(value);
  }
  if (Array.isArray(value)) {
    return `[${value.map(canonicalString).join(",")}]`;
  }
  if (typeof value === "object") {
    const obj = value as Record<string, unknown>;
    const keys = Object.keys(obj).sort(compareCodePoints);
    const parts = keys.map((k) => {
      checkBatchString(k);
      return `${JSON.stringify(k)}:${canonicalString(obj[k])}`;
    });
    return `{${parts.join(",")}}`;
  }
  throw new ClaimError(`unsupported type in batch: ${typeof value}`);
}

export class ClaimError extends Error {}

/* ---------------- claim shapes (mirror of claims.py) ---------------- */

export const BATCH_VERSION = 1;
export const SOULID_VERSION = "kinded_v2";
export const MAX_CLAIMS_PER_BATCH = 50_000;
export const BACKFILL_DAILY_CLAIMS = 50_000;
export const STEADY_DAILY_CLAIMS = 5_000;
export const BACKFILL_WINDOW_MS = 30 * 24 * 60 * 60 * 1000;
export const RETENTION_MS = 90 * 24 * 60 * 60 * 1000;
const MAX_NAME_CHARS = 512;

const SUBJECT_RE = /^soul_[0-9a-f]{16}$/;

/** Python str.strip()'s whitespace set (str.isspace): JS trim()
 *  disagrees both ways — "\x1c" is blank in Python but not JS,
 *  "\ufeff" the reverse — so the blank check uses this set. */
const PYTHON_WHITESPACE = new Set([
  ..."\t\n\v\f\r \u001c\u001d\u001e\u001f\u0085\u00a0\u1680",
  ...Array.from({ length: 11 }, (_, i) => String.fromCodePoint(0x2000 + i)),
  "\u2028", "\u2029", "\u202f", "\u205f", "\u3000",
]);
function isPythonBlank(s: string): boolean {
  return [...s].every((ch) => PYTHON_WHITESPACE.has(ch));
}
const KINDS = ["artist", "album", "track"] as const;
const PROVIDER_ID_FIELDS = [
  "spotify_id", "deezer_id", "tidal_id", "itunes_id", "discogs_id",
  "hydrabase_id",
];
const MBID_FIELDS = ["artist_mbid", "release_group_mbid", "recording_mbid"];
const ALL_FIELDS = new Set([
  ...PROVIDER_ID_FIELDS,
  ...MBID_FIELDS,
  "isrc", "duration_ms", "year", "genres", "label",
  "name", "display_name", "album_track", "provider_link",
]);
const SOURCES = new Set([
  "musicbrainz", "spotify", "deezer", "tidal", "itunes", "discogs",
  "hydrabase", "file_tags", "user_edit",
]);
const RESERVED_SOURCES = new Set(["user_edit"]); // G2: nothing may emit it in v1
const NAME_ARITY: Record<string, number> = { artist: 1, album: 2, track: 2 };

/** Exported for the cross-language drift test: the Python fixture
 *  carries the same lists from claims.py and the test asserts the two
 *  implementations agree exactly (see metasync-claims.test.ts). */
export const CLAIM_KINDS: readonly string[] = KINDS;
export const CLAIM_FIELDS: readonly string[] = [...ALL_FIELDS].sort();
export const CLAIM_SOURCES: readonly string[] = [...SOURCES].sort();

export interface Claim {
  subject: string;
  kind: string;
  field: string;
  value: unknown;
  source: string;
  soulid_version: string;
}

function isPlainObject(v: unknown): v is Record<string, unknown> {
  return typeof v === "object" && v !== null && !Array.isArray(v);
}

/** Structural validation of one claim — claims.py validate_claim,
 *  minus the SoulID recompute (see the header note). */
export function validateClaim(claim: unknown): Claim {
  if (!isPlainObject(claim)) throw new ClaimError("claim must be an object");
  const { subject, kind, field, source } = claim as Record<string, unknown>;
  if (typeof subject !== "string" || !SUBJECT_RE.test(subject)) {
    throw new ClaimError("claim.subject must be a SoulID string");
  }
  if (typeof kind !== "string" || !(KINDS as readonly string[]).includes(kind)) {
    throw new ClaimError("claim.kind invalid");
  }
  if (typeof field !== "string" || !ALL_FIELDS.has(field)) {
    throw new ClaimError(`unknown claim field: ${String(field)}`);
  }
  if (typeof source !== "string" || !SOURCES.has(source)) {
    throw new ClaimError(`unknown claim source: ${String(source)}`);
  }
  if (RESERVED_SOURCES.has(source)) {
    throw new ClaimError(`claim source ${source} is reserved in v1 (G2)`);
  }
  if (claim.soulid_version !== SOULID_VERSION) {
    throw new ClaimError("claim.soulid_version must be kinded_v2");
  }
  if (!("value" in claim)) throw new ClaimError("claim.value missing");
  const value = claim.value;
  if (field === "name" || field === "display_name") {
    const arity = NAME_ARITY[kind as string];
    if (
      !Array.isArray(value) || value.length !== arity ||
      !value.every((p) => typeof p === "string")
    ) {
      throw new ClaimError(`${field} claim value must be the name-parts list`);
    }
    // Length is in CODE POINTS, like Python's len() (JS .length
    // counts UTF-16 units and would refuse astral names Python
    // accepted).
    if (value.some((p) => [...(p as string)].length > MAX_NAME_CHARS)) {
      throw new ClaimError("name part over length cap");
    }
    if (value.some((p) => isPythonBlank(p as string))) {
      throw new ClaimError("name part must not be blank");
    }
  } else if (
    [...PROVIDER_ID_FIELDS, ...MBID_FIELDS, "isrc"].includes(field)
  ) {
    if (typeof value !== "string" || !value) {
      throw new ClaimError(`${field} claim value must be a string`);
    }
  } else if (field === "duration_ms") {
    if (typeof value !== "number" || !Number.isInteger(value) || value < 0) {
      throw new ClaimError("duration_ms claim value must be int ms");
    }
  } else if (field === "year") {
    if (typeof value !== "number" || !Number.isInteger(value)) {
      throw new ClaimError("year claim value must be an int");
    }
  } else if (field === "genres" || field === "label") {
    if (typeof value !== "string" || !value) {
      throw new ClaimError(`${field} claim value must be a string`);
    }
  } else if (field === "album_track") {
    if (!isPlainObject(value)) {
      throw new ClaimError("album_track value must be an object");
    }
    const keys = Object.keys(value).sort();
    if (keys.join(",") !== "disc,position,track,variant") {
      throw new ClaimError(
        "album_track value needs exactly track/disc/position/variant");
    }
    if (typeof value.track !== "string" || !SUBJECT_RE.test(value.track)) {
      throw new ClaimError("album_track track must be a SoulID string");
    }
    for (const k of ["disc", "position"] as const) {
      const v = value[k];
      if (typeof v !== "number" || !Number.isInteger(v) || v < 1) {
        throw new ClaimError(`album_track ${k} must be a positive int`);
      }
    }
    if (value.variant !== null && typeof value.variant !== "string") {
      throw new ClaimError("album_track variant must be a string or null");
    }
  }
  canonicalBytes(claim); // the claim itself must be canonicalizable
  return claim as unknown as Claim;
}

/** A retraction identifies one previously-sent claim (§6). */
export function validateRetraction(r: unknown): Claim {
  return validateClaim(r);
}

export const MAX_RETRACTIONS_PER_BATCH = 5_000;

export interface Batch {
  header: { version: number; node: string; claim_count: number; nonce: string };
  claims: Claim[];
  retractions: Claim[];
}

/** Validate a batch payload (unsigned form): header, caps, per-claim
 *  shapes, and the one-name-claim-per-subject rule. */
export function validateBatch(batch: unknown): Batch {
  if (!isPlainObject(batch)) throw new ClaimError("batch must be an object");
  const header = batch.header;
  if (!isPlainObject(header)) throw new ClaimError("batch header missing");
  if (header.version !== BATCH_VERSION) {
    throw new ClaimError("unsupported batch version");
  }
  if (typeof header.node !== "string" || !header.node) {
    throw new ClaimError("batch header node missing");
  }
  if (typeof header.nonce !== "string" || !header.nonce) {
    throw new ClaimError("batch header nonce missing");
  }
  const claims = batch.claims;
  if (!Array.isArray(claims)) throw new ClaimError("batch claims missing");
  if (claims.length > MAX_CLAIMS_PER_BATCH) {
    throw new ClaimError("batch over claim cap");
  }
  if (header.claim_count !== claims.length) {
    throw new ClaimError("claim_count does not match claims");
  }
  const validated = claims.map(validateClaim);
  const seenNames = new Set<string>();
  for (const c of validated) {
    if (c.field === "name") {
      if (seenNames.has(c.subject)) {
        throw new ClaimError("duplicate name claim for subject in one batch");
      }
      seenNames.add(c.subject);
    }
  }
  const retractions = batch.retractions === undefined ? [] : batch.retractions;
  if (!Array.isArray(retractions)) {
    // null is refused, exactly like Python (an absent key is the only
    // way to say "no retractions").
    throw new ClaimError("retractions must be a list");
  }
  if (retractions.length > MAX_RETRACTIONS_PER_BATCH) {
    throw new ClaimError("batch over retraction cap");
  }
  return {
    header: header as Batch["header"],
    claims: validated,
    retractions: retractions.map(validateRetraction),
  };
}

/* ---------------- batch signature ---------------- */

export function batchDigest(batch: unknown): string {
  return sha256Hex(canonicalBytes(batch));
}

/** Verify the envelope signature: Ed25519 over the batch digest bytes,
 *  by the key named in the batch header. */
export function verifyBatchSignature(
  publicKeyB64: string,
  batch: unknown,
  signatureB64: string,
): boolean {
  const sig = decodeBase64Url(signatureB64, 64);
  const raw = decodeBase64Url(publicKeyB64, 32);
  if (!sig || !raw) return false;
  const key = ed25519PublicKeyObject(raw);
  if (!key) return false;
  try {
    const digest = Buffer.from(batchDigest(batch), "hex");
    return cryptoVerify(null, digest, key, sig);
  } catch {
    return false;
  }
}

/* ---------------- blinds + allowances (§9/§12) ---------------- */

/** The account blind a claim is stored under (Q1). */
export function accountBlind(secret: string, userId: string): string {
  return createHmac("sha256", secret).update(userId).digest("hex");
}

/** Claims/day allowance for an account: backfill for the first 30
 *  days after contributor approval, steady state after (§6). */
export function dailyAllowance(
  contributorApprovedAt: Date | null,
  now: Date = new Date(),
): number {
  if (
    contributorApprovedAt &&
    now.getTime() - contributorApprovedAt.getTime() < BACKFILL_WINDOW_MS
  ) {
    return BACKFILL_DAILY_CLAIMS;
  }
  return STEADY_DAILY_CLAIMS;
}

/** SHA-256 hex of a claim value's canonical form — the dedupe key. */
export function valueHash(value: unknown): string {
  return sha256Hex(canonicalBytes(value));
}

/* ---------------- §3A.2 node request door ----------------
 * Header parsing and request verification live here (not imported
 * from src/sin/index.ts) so this function never has to import the
 * SIN app module; the cryptography itself (canonical string +
 * Ed25519) is shared via src/sin/logic.ts. Keep the header set in
 * sync with parseNodeHeaders in src/sin/index.ts. */

export interface NodeSignatureHeaders {
  nodeId: string;
  signature: Buffer;
  timestamp: string;
  timestampSeconds: number;
  nonce: string;
  publicKeyRaw: Buffer | null;
}

const NODE_ID_SHAPE = /^[0-9a-f]{64}$/;
const NONCE_SHAPE = /^[A-Za-z0-9_-]{16,128}$/;

export function parseNodeHeaders(
  request: Request,
): NodeSignatureHeaders | null {
  const nodeId = request.headers.get("x-node-id");
  const signatureHeader = request.headers.get("x-node-signature");
  const timestamp = request.headers.get("x-node-timestamp");
  const nonce = request.headers.get("x-node-nonce");
  if (!nodeId || !NODE_ID_SHAPE.test(nodeId)) return null;
  if (!timestamp || !/^\d+$/.test(timestamp)) return null;
  const timestampSeconds = Number(timestamp);
  if (!Number.isSafeInteger(timestampSeconds)) return null;
  if (!nonce || !NONCE_SHAPE.test(nonce)) return null;
  const signature = signatureHeader
    ? decodeBase64Url(signatureHeader, 64)
    : null;
  if (!signature) return null;
  const publicKeyPresented = request.headers.get("x-node-public-key");
  let publicKeyRaw: Buffer | null = null;
  if (publicKeyPresented !== null) {
    publicKeyRaw = decodeBase64Url(publicKeyPresented, 32);
    if (!publicKeyRaw) return null;
  }
  return { nodeId, signature, timestamp, timestampSeconds, nonce, publicKeyRaw };
}

function rawPathAndQuery(requestUrl: string): string {
  try {
    const schemeEnd = requestUrl.indexOf("://");
    if (schemeEnd === -1) return requestUrl;
    const pathStart = requestUrl.indexOf("/", schemeEnd + 3);
    return pathStart === -1 ? "/" : requestUrl.slice(pathStart);
  } catch {
    return requestUrl;
  }
}

export function verifyNodeRequest(
  request: Request,
  headers: NodeSignatureHeaders,
  publicKeyRaw: Uint8Array,
  bodyText: string,
  now: Date = new Date(),
): boolean {
  if (!isTimestampWithinWindow(headers.timestampSeconds, now)) return false;
  return verifyNodeSignature({
    publicKeyRaw,
    method: request.method,
    pathAndQuery: rawPathAndQuery(request.url),
    timestamp: headers.timestamp,
    nonce: headers.nonce,
    body: bodyText,
    signature: headers.signature,
  });
}
